"use client";

import { useState, useRef } from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import {
  Mail01Icon,
  Linkedin01Icon,
  Facebook01Icon,
  GithubIcon,
} from "@hugeicons/core-free-icons";

// Pull these from env vars instead of hardcoding them in the component.
// Add to your .env.local (and your host's env settings):
//   NEXT_PUBLIC_CONTACT_EMAIL=you@example.com
//   NEXT_PUBLIC_LINKEDIN_URL=https://linkedin.com/in/yourhandle
//   NEXT_PUBLIC_FACEBOOK_URL=https://facebook.com/yourhandle
//   NEXT_PUBLIC_GITHUB_URL=https://github.com/yourhandle
//
// Note: anything prefixed NEXT_PUBLIC_ is still bundled into client JS —
// that's unavoidable if a browser button needs to open the link. This
// approach just keeps the values out of your source code / git history,
// not out of the shipped bundle. If you want the email to never appear
// in the page source at all, see the /api/contact route idea at the
// bottom of this file's comments.

const EMAIL = process.env.NEXT_PUBLIC_CONTACT_EMAIL ?? "";
const LINKEDIN_URL = process.env.NEXT_PUBLIC_LINKEDIN_URL ?? "";
const FACEBOOK_URL = process.env.NEXT_PUBLIC_FACEBOOK_URL ?? "";
const GITHUB_URL = process.env.NEXT_PUBLIC_GITHUB_URL ?? "";

function SocialLink({
  href,
  label,
  icon,
}: {
  href: string;
  label: string;
  icon: Parameters<typeof HugeiconsIcon>[0]["icon"];
}) {
  if (!href) return null;
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className="group flex items-center gap-1.5 text-white/40 transition-colors hover:text-white"
      aria-label={label}
    >
      <HugeiconsIcon icon={icon} size={14} color="currentColor" strokeWidth={1.75} />
      <span className="hidden sm:inline">{label}</span>
    </a>
  );
}

export default function Footer() {
  const [toastVisible, setToastVisible] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleCopyEmail = async () => {
    if (!EMAIL) return;
    try {
      await navigator.clipboard.writeText(EMAIL);
    } catch {
      // Fallback for older/insecure contexts where clipboard API is unavailable
      const el = document.createElement("textarea");
      el.value = EMAIL;
      el.style.position = "fixed";
      el.style.opacity = "0";
      document.body.appendChild(el);
      el.focus();
      el.select();
      document.execCommand("copy");
      document.body.removeChild(el);
    }

    setToastVisible(true);
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => setToastVisible(false), 2000);
  };

  return (
    <footer
      data-nav-theme="dark"
      className="relative border-t border-white/10 bg-[var(--ink)] px-6 py-6 md:px-12 lg:px-20"
    >
      <div className="mx-auto flex w-full max-w-[1700px] flex-col gap-4 text-[10px] font-medium uppercase tracking-[0.14em] text-white/22 md:flex-row md:items-center md:justify-between md:gap-6 md:text-[11px]">
        <p>Copyright {new Date().getFullYear()} Vergel B. Villaranda</p>

        <div className="flex items-center gap-5">
          {EMAIL && (
            <button
              type="button"
              onClick={handleCopyEmail}
              className="group flex items-center gap-1.5 text-white/40 transition-colors hover:text-white"
              aria-label="Copy email address"
            >
              <HugeiconsIcon icon={Mail01Icon} size={14} color="currentColor" strokeWidth={1.75} />
              <span className="hidden sm:inline">Email</span>
            </button>
          )}

          <SocialLink href={LINKEDIN_URL} label="LinkedIn" icon={Linkedin01Icon} />
          <SocialLink href={FACEBOOK_URL} label="Facebook" icon={Facebook01Icon} />
          <SocialLink href={GITHUB_URL} label="GitHub" icon={GithubIcon} />
        </div>

        <p>Designed and Built by Ver.dev</p>
      </div>

      {/* Toast */}
      <div
        aria-live="polite"
        className={`pointer-events-none fixed bottom-6 left-1/2 z-50 -translate-x-1/2 transition-all duration-300 ${
          toastVisible
            ? "translate-y-0 opacity-100"
            : "translate-y-2 opacity-0"
        }`}
      >
        <div className="rounded-full border border-white/10 bg-[var(--ink)] px-4 py-2 text-[11px] font-medium uppercase tracking-[0.1em] text-white shadow-lg shadow-black/40">
          Email copied
        </div>
      </div>
    </footer>
  );
}